const fs=require('fs'),sharp=require('sharp'),crypto=require('crypto');
(async()=>{
const file='public/images/kpl/website-top-50/manifest.json'; const manifest=JSON.parse(fs.readFileSync(file,'utf8'));
const replacements=[
 [6,'summer-lawn','IMG_7111.jpeg','The Lodge, stone firepit, lawn and shoreline lounge chair in summer'],
 [7,'autumn-lawn','IMG_0124.jpeg','Autumn trees framing the Lodge, lawn and stone firepit'],
 [23,'tiled-bedroom','IMG_7402.jpeg','Tiled-floor bedroom with white bedding, pale blue throw and folded towels'],
 [25,'wood-bedroom','IMG_7093.jpeg','Wood-floor bedroom with white bedding, tan throw, folded towels and sailboat artwork'],
 [27,'bunk-room','IMG_6996.jpeg','White twin-over-full bunk bed, blue rug, window and writing table']
];
for(const [order,key,sourceFile,alt] of replacements){const p=manifest.photos.find(p=>p.order===order);const src='/images/kpl/2026-10-28/kendall-pond-lodge-'+key+'-premium.webp';const bytes=fs.readFileSync('public'+src);const meta=await sharp(bytes).metadata();const old=p.src;Object.assign(p,{src,alt,width:meta.width,height:meta.height,sourceFile,replaces:old,treatment:'Non-generative Adobe tonal correction'+(order>=23?', perspective correction':'')+'; WebP export. No objects, architecture or furnishings generated.',sha256:crypto.createHash('sha256').update(bytes).digest('hex'),bytes:bytes.length});delete p.captureDate;}
fs.writeFileSync(file,JSON.stringify(manifest,null,2)+'\n');
let p='app/lodge/page.tsx',s=fs.readFileSync(p,'utf8');s=s.replace('import Link from "next/link";','import Link from "next/link";\nimport { lodgePhoto } from "@/app/_data/lodge-photos";');s=s.replace('export default function LodgePage() {','export default function LodgePage() {\n  const woodBedroom = lodgePhoto(25);\n  const tiledBedroom = lodgePhoto(23);\n  const bunkRoom = lodgePhoto(27);');
s=s.replace('<PhotoCard src="/images/kpl/king-room.jpg" alt="King bedroom" title="King room" note="King bed" />','<PhotoCard src={woodBedroom.src} alt={woodBedroom.alt} title="Wood-floor bedroom" note="White bedding · folded towels" />');s=s.replace('<PhotoCard src="/images/kpl/queen-room.jpg" alt="Queen bedroom" title="Queen room" note="Queen bed" />','<PhotoCard src={tiledBedroom.src} alt={tiledBedroom.alt} title="Tiled bedroom" note="Blue throw · folded towels" />');s=s.replace('<PhotoCard src="/images/kpl/website-top-50/05-Bedrooms/26-kendall-pond-lodge-bunk-room-wide.jpg" alt="Bunk room" title="Bunk room" note="Twin over full" />','<PhotoCard src={bunkRoom.src} alt={bunkRoom.alt} title="Bunk room" note="Twin over full" />');fs.writeFileSync(p,s);
p='app/grounds/page.tsx';s=fs.readFileSync(p,'utf8').replace('import Link from "next/link";','import Link from "next/link";\nimport { lodgePhoto } from "@/app/_data/lodge-photos";').replace('export default function GroundsPage() {','export default function GroundsPage() {\n  const firepit = lodgePhoto(6);');s=s.replace('src="/images/kpl/website-top-50/09-Waterfront-and-Grounds/40-kendall-pond-lodge-summer-firepit-and-shoreline.jpg" alt="Firepit by Kendall Pond"','src={firepit.src} alt={firepit.alt}');fs.writeFileSync(p,s);
p='tests/curated-gallery.test.mjs';s=fs.readFileSync(p,'utf8').replace('assert.match(photo.src, /^\\/images\\/kpl\\/website-top-50\\//);','assert.match(photo.src, /^\\/images\\/kpl\\/(website-top-50|2026-10-28)\\//);').replace('assert.match(photo.src, /\\.jpg$/);','assert.match(photo.src, /\\.(jpg|webp)$/);');s+='\ntest("premium replacements preserve gallery size and original property details", () => {\n  const expected = new Map([[6,"summer-lawn"],[7,"autumn-lawn"],[23,"tiled-bedroom"],[25,"wood-bedroom"],[27,"bunk-room"]]);\n  for (const [order, name] of expected) {\n    const photo = manifest.photos.find(item => item.order === order);\n    assert.ok(photo.src.endsWith(name + "-premium.webp"));\n    assert.match(photo.treatment, /Non-generative/);\n    assert.match(photo.sha256, /^[a-f0-9]{64}$/);\n    assert.ok(photo.sourceFile && photo.replaces);\n  }\n  const lodge = readFileSync(new URL("../app/lodge/page.tsx", import.meta.url), "utf8");\n  assert.doesNotMatch(lodge, /src="\\/images\\/kpl\\/(king|queen)-room\\.jpg"/);\n  assert.match(lodge, /<SleepPlan \\/>/);\n});\n';fs.writeFileSync(p,s);
})().catch(e=>{console.error(e);process.exit(1)});
